from collections import deque

def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Priority queue for BFS
    queue = deque([(source, 0)])

    while queue:
        node, distance = queue.popleft()
        if node == target:
            break
        for neighbour, weight in graph[node]:
            new_distance = distance + weight
            if new_distance < distances[neighbour]:
                distances[neighbour] = new_distance
                path[neighbour] = node
                queue.append((neighbour, new_distance))

    # If target is not reachable, distances[target] will be infinity
    if distances[target] == float('inf'):
        return float('inf'), None
    else:
        # Reconstruct the path
        path_list = deque()
        current = target
        while current:
            path_list.appendleft(current)
            current = path[current]
        return distances[target], list(path_list)

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source = 'A'
target = 'D'

distance, path = shortest_path(graph, source, target)
print(f"Shortest distance from {source} to {target}: {distance}")
print(f"Path: {path}")
